package akogen.fabric.v6;
import java.nio.file.*;import java.util.*;import com.google.gson.*;
public class VisibilityChecks{
 public static class Font{public int width(String s){return s.length()*6;}}
 public static class MC{public Object font=new Font(),player=new SyncChecks.Player(1,0);}
 public static class Screen{public int width=854,height=480;}
 public static class Pose{public Pose pushMatrix(){return this;}public Pose popMatrix(){return this;}public Pose translate(float x,float y){return this;}public Pose scale(float x,float y){return this;}}
 public static class Graphics{public Pose method_51448(){return new Pose();}List<String> labels=new ArrayList<String>();public void fill(int a,int b,int c,int d,int color){}public int drawString(Object f,String s,int x,int y,int color,boolean shadow){labels.add(s);return 0;}}
 public static class Click{double px,py;Click(int x,int y){px=x;py=y;}public int button(){return 0;}public double x(){return px;}public double y(){return py;}}
 static void require(boolean ok,String msg){if(!ok)throw new AssertionError(msg);}
 public static void main(String[] args)throws Exception{Names.loader=VisibilityChecks.class.getClassLoader();Names.names=new JsonParser().parse(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8")).getAsJsonObject();Session.mc=new MC();Path folder=Files.createTempDirectory("akogen-visibility-");Session.logPath=folder.resolve("session.log").toString();Assets.Entry mine=new Assets.Entry(),other=new Assets.Entry();mine.id=1;other.id=2;Session.equipped.put("hat",mine);CosmeticSync.Remote remote=new CosmeticSync.Remote();remote.equipped.put("hat",other);CosmeticSync.byEntity.put(2,remote);
 for(Visibility.Mode mode:Visibility.Mode.values()){Visibility.set(mode);require(Visibility.local()==(mode!=Visibility.Mode.DISABLED),"Local filter");require(Visibility.others()==(mode==Visibility.Mode.ENABLED),"Peer filter");require(CosmeticSync.selectionForEntity(1).containsValue(mine)==Visibility.local(),"Local cape filter");require(CosmeticSync.selectionForEntity(2).containsValue(other)==Visibility.others(),"Peer cape filter");Visibility.mode=Visibility.Mode.ENABLED;Visibility.load();require(Visibility.mode==mode||mode==Visibility.Mode.ENABLED,"Persistence");require(Session.equipped.get("hat")==mine&&remote.equipped.get("hat")==other,"Selections lost");if(mode==Visibility.Mode.DISABLED)World.draw(null);}
 Graphics graphics=new Graphics();Screen screen=new Screen();Assets.entries.clear();Visibility.mode=Visibility.Mode.ENABLED;for(int sw:new int[]{854,426,320}){screen.width=sw;screen.height=sw==854?480:240;for(Visibility.Mode mode:Visibility.Mode.values()){Ui.render(screen,graphics,0,0,0);require(Session.lastError==null,"Menu render failed "+Session.lastError);Ui.Hit button=null;for(Ui.Hit hit:Ui.hits)if(hit.kind==4)button=hit;require(button!=null,"No mode button");Ui.Hit close=null;for(Ui.Hit hit:Ui.hits)if(hit.kind==3)close=hit;require(close!=null&&button.x+button.w==close.x-6&&button.y==close.y,"Mode button is not immediately left of close");require(button.x>=Ui.x&&button.x+button.w<=Ui.x+Ui.w,"Header button outside panel");Ui.click(new Click(button.x+2,button.y+2),false);require(Ui.modeMenu,"Menu not open");Ui.render(screen,graphics,0,0,0);Ui.Hit option=null;for(Ui.Hit hit:Ui.hits)if(hit.kind==5&&hit.index==mode.ordinal())option=hit;require(option!=null,"Option missing");Ui.click(new Click(option.x+3,option.y+3),false);require(Visibility.mode==mode&&!Ui.modeMenu,"Mode click failed");}}
 for(Visibility.Mode mode:Visibility.Mode.values())require(graphics.labels.contains(mode.label),"Exact mode label missing");System.out.println("PASS all three viewing filters, unchanged equipped selections, persistence, disabled early-out, exact menu labels and dropdown click ordering");}
}
